import{_ as o,C as r,o as i,c as d,a2 as e,E as n}from"./chunks/framework.DTdEDYjJ.js";const g=JSON.parse('{"title":"开始使用 Bot Studio","description":"从本机运行开始，为长期存在的个人 Bot 选择模型、执行内核与运行主机。","frontmatter":{"title":"开始使用 Bot Studio","description":"从本机运行开始，为长期存在的个人 Bot 选择模型、执行内核与运行主机。"},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md"}'),s={name:"guide/overview.md"};function h(p,t,l,u,b,m){const a=r("PlatformCards");return i(),d("div",null,[t[0]||(t[0]=e('<h1 id="开始使用-bot-studio" tabindex="-1">开始使用 Bot Studio <a class="header-anchor" href="#开始使用-bot-studio" aria-label="Permalink to &quot;开始使用 Bot Studio&quot;">​</a></h1><p>Bot Studio（原 OpenBot）是一个 <strong>Personal Bot Harness</strong>：你管理的是长期存在的 Bot，每个 Bot 可以有自己的职责、模型、执行内核、记忆和工作空间。任务与执行实例按需创建，身份与责任记录持续保留。</p><p>从自己的 Mac 开始，需要常开执行或多端访问时再增加 Node。云主机、模型服务和 Bot Studio 分别选择，不要求先购买官方托管服务。</p><p>网页交互预览无需安装。Mac 试点 DMG 需要仓库权限，1.0.33 为开发方本机验收版本。首次使用前请查看<a href="/openbot/guide/platforms.html">平台与下载</a>和<a href="/openbot/guide/status.html">支持范围与验证状态</a>。</p><h2 id="选择你的平台" tabindex="-1">选择你的平台 <a class="header-anchor" href="#选择你的平台" aria-label="Permalink to &quot;选择你的平台&quot;">​</a></h2>',5)),n(a,{compact:"","id-prefix":"platform-overview"}),t[1]||(t[1]=e(`<p>各端安装入口和开发进度见<a href="/openbot/guide/platforms.html">平台与下载</a>。公开包、当前源码和官网示例的版本分别说明。</p><h2 id="选择一条最短路径" tabindex="-1">选择一条最短路径 <a class="header-anchor" href="#选择一条最短路径" aria-label="Permalink to &quot;选择一条最短路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的目标</th><th>起点</th><th>需要准备</th></tr></thead><tbody><tr><td>在 Mac 使用内置 Bot</td><td><a href="/openbot/guide/quickstart.html">本机快速开始</a></td><td>Mac arm64、模型 API 连接</td></tr><tr><td>复用已登录的本机智能体</td><td><a href="/openbot/guide/quickstart.html#复用本机智能体">快速开始：本机智能体</a></td><td>支持的 CLI 已安装并登录</td></tr><tr><td>手机访问自己的 Mac</td><td><a href="/openbot/guide/requirements.html#第二档-mac-就是你的-bot-服务器">使用门槛与运行方式</a></td><td>持续运行的 Mac、可互通局域网、独立预览 Hub 与设备授权</td></tr><tr><td>让任务在服务器持续执行</td><td><a href="/openbot/deployment/self-host.html">部署 Linux Node</a></td><td>Linux、Docker、SSH、节点自己的模型配置</td></tr><tr><td>统一应用授权，供主 Bot 使用</td><td><a href="/openbot/guide/app-authorizations.html">自托管应用授权</a></td><td>自建 Node、专用 OAuth App、明确的 Bot 动作授权</td></tr></tbody></table><p>手机联动仍是独立开发原型；USB 真实任务、LAN 配对和公网云端 App 是不同的验证范围。当前没有官方托管购买入口或跨设备自动发现。</p><h2 id="从源码启动" tabindex="-1">从源码启动 <a class="header-anchor" href="#从源码启动" aria-label="Permalink to &quot;从源码启动&quot;">​</a></h2><p>需要主仓访问权限、Node.js 22.19+ 与 npm。在仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OPENBOT_USERDATA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Library/Application Support/openbot-dev&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>开发数据放在仓库外，与日常安装的数据分开。启动后先<a href="/openbot/guide/models.html">接入模型</a>并确认真实文字回复，再按任务需要开启工具。</p><h2 id="理解-openbot-的边界" tabindex="-1">理解 OpenBot 的边界 <a class="header-anchor" href="#理解-openbot-的边界" aria-label="Permalink to &quot;理解 OpenBot 的边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>OpenBot 负责什么</th></tr></thead><tbody><tr><td>Bot</td><td>身份、职责、记忆边界、任务与结果记录</td></tr><tr><td>Harness</td><td>适配默认 DSH、显式 Pi 或兼容工具循环；不随切换增加权限</td></tr><tr><td>工作屏幕</td><td>独立 Chromium 浏览器、观察、逐次审批、人工接管与停止</td></tr><tr><td>Node</td><td>在选定机器上执行，使用自己的配置、凭据和持久状态</td></tr><tr><td>应用授权</td><td>服务器保存凭据，按 Bot 和动作授予能力；模型只接收业务结果</td></tr></tbody></table><p>默认界面保留对话和必要进度，低频选项放在设置与高级入口。收起细节不会取消审批、停止和责任记录。</p><h2 id="按角色继续阅读" tabindex="-1">按角色继续阅读 <a class="header-anchor" href="#按角色继续阅读" aria-label="Permalink to &quot;按角色继续阅读&quot;">​</a></h2><ul><li><strong>使用者</strong>：<a href="/openbot/guide/using-bot-studio.html">Bot Studio 使用指南</a> → <a href="/openbot/guide/quickstart.html">本机快速开始</a> → <a href="/openbot/guide/computer-use.html">浏览器工作屏幕</a>。</li><li><strong>部署者</strong>：<a href="/openbot/deployment/overview.html">运行环境</a> → <a href="/openbot/deployment/self-host.html">Linux Node</a> → <a href="/openbot/deployment/network.html">网络连接</a> → <a href="/openbot/guide/app-authorizations.html">应用授权</a>。</li><li><strong>开发者</strong>：<a href="/openbot/development/architecture-report.html">技术架构报告</a> → <a href="/openbot/development/integrate-and-publish.html">接入 Bot 与发布连接器</a> → <a href="/openbot/reference/node-api.html">Node API</a> → <a href="/openbot/development/contributing.html">参与贡献</a>。</li></ul><p>源码与问题反馈：<a href="https://github.com/Harzva/openbot" target="_blank" rel="noreferrer">GitHub 仓库</a>。文档来自同一份 <code>website/</code> 源码，发布到 <a href="https://wave.sh.cn/openbot/guide/overview.html" target="_blank" rel="noreferrer">wave</a> 与 <a href="https://harzva.github.io/openbot/guide/overview.html" target="_blank" rel="noreferrer">GitHub Pages</a>；当前新版内容需分别验收。双站构建与部署方式见<a href="/openbot/development/contributing.html#文档站开发">文档维护说明</a>。</p>`,14))])}const f=o(s,[["render",h]]);export{g as __pageData,f as default};
